"""End-to-end triage workflow with audit trail."""
from __future__ import annotations

import json
import time
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Callable

from .alerts import Alert
from .policy_decision import PolicyDecision, PolicyQuestion, SEVERITY_QUESTION
from .explainer import Explanation

# Fixed policy text (deterministic, written by developer, not generated by a model)
POLICY_ACTIONS = {
    "LOW": "Log and continue routine monitoring.",
    "MEDIUM": "Queue for analyst investigation.",
    "HIGH": "ESCALATE TO A HUMAN ANALYST for urgent review. This tool never blocks IPs, deletes files, or runs commands.",
}


@dataclass
class TriageResult:
    alert: Alert
    decision: PolicyDecision
    explanation: Explanation
    policy_action: str


def triage(alert: Alert, decider, explainer: Callable[[Alert, PolicyDecision], Explanation],
           question: PolicyQuestion = SEVERITY_QUESTION, audit_path: str | None = "audit/audit_log.jsonl") -> TriageResult:
    decision = decider.decide(alert.to_state(), question)
    explanation = explainer(alert, decision)
    result = TriageResult(alert, decision, explanation, POLICY_ACTIONS[decision.option])
    if audit_path:
        write_audit(result, audit_path)
    return result


def write_audit(result: TriageResult, path: str) -> None:
    d = result.decision
    record = {
        "timestamp_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "alert": asdict(result.alert),
        "decision": {
            "option": d.option, "source": d.source,
            "confidence": None if d.confidence != d.confidence else d.confidence,
            "confidence_source": d.confidence_source,
            "probabilities": d.probabilities, "latency_ms": d.latency_ms,
        },
        "explanation": {
            "status": result.explanation.status,
            "note": "Generated text is the Bedrock model's explanation, NOT Decider's reasoning. Decider returns only probabilities.",
            "text": result.explanation.text, "error": result.explanation.error,
            "tool_calls_allowed": result.explanation.gate_allowed,
            "tool_calls_denied": result.explanation.gate_denied,
        },
        "policy_action": result.policy_action,
    }
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("a", encoding="utf-8") as f:
        f.write(json.dumps(record) + "\n")